import{_ as l,c as i,o as e,aj as k}from"./chunks/framework.rJ-FfUda.js";const d=JSON.parse('{"title":"kafka","description":"","frontmatter":{"title":"kafka","hugoSource":"computer-science/distributed-system/message-queue/kafka.md","outline":[1,6]},"headers":[],"relativePath":"computer-science/distributed-system/message-queue/2026-11-17-kafka.md","filePath":"computer-science/distributed-system/message-queue/2026-11-17-kafka.md"}'),r={name:"computer-science/distributed-system/message-queue/2026-11-17-kafka.md"};function t(s,a,o,u,n,c){return e(),i("div",null,[...a[0]||(a[0]=[k('<h1 id="kafka" tabindex="-1">kafka <a class="header-anchor" href="#kafka" aria-label="Permalink to “kafka”">​</a></h1><h2 id="kafka-vs-rocketmq" tabindex="-1">kafka vs rocketmq <a class="header-anchor" href="#kafka-vs-rocketmq" aria-label="Permalink to “kafka vs rocketmq”">​</a></h2><ul><li><a href="https://zhuanlan.zhihu.com/p/341156308" target="_blank" rel="noreferrer">Kafka 和 RocketMQ 之性能对比</a></li></ul><h2 id="kafka如何实现高吞吐量的" tabindex="-1">kafka如何实现高吞吐量的？ <a class="header-anchor" href="#kafka如何实现高吞吐量的" aria-label="Permalink to “kafka如何实现高吞吐量的？”">​</a></h2><ul><li>顺序读写</li><li>零拷贝</li><li>分区与并行处理</li><li>批量发送</li><li>数据压缩</li><li>页缓存</li><li>高效的日志存储(将消息分段、并建立索引文件、支持快速定位与消息读取)</li></ul><h2 id="kafka突然宕机了消息会不会丢失" tabindex="-1">Kafka突然宕机了消息会不会丢失 <a class="header-anchor" href="#kafka突然宕机了消息会不会丢失" aria-label="Permalink to “Kafka突然宕机了消息会不会丢失”">​</a></h2><ul><li>消息的持久化机制 <ul><li>消息会存储到日志文件中，宕机后不会丢失</li></ul></li><li>副本机制 <ul><li>一个分区可以建立副本，确保数据不丢失</li></ul></li><li>生产者确认机制</li><li>刷盘机制 <ul><li>同步刷盘, 每次写入消息就将写入到磁盘中, 但损失了效率</li><li>异步刷盘</li></ul></li></ul><h2 id="kafka如何保障顺序消费" tabindex="-1">kafka如何保障顺序消费 <a class="header-anchor" href="#kafka如何保障顺序消费" aria-label="Permalink to “kafka如何保障顺序消费”">​</a></h2><ul><li>分区内的顺序性</li><li>将分区键与业务ID进行绑定，保证相同业务的消息都发送到对应分区进行顺序消费</li></ul><h2 id="kafka重平衡的触发条件是什么" tabindex="-1">kafka重平衡的触发条件是什么？ <a class="header-anchor" href="#kafka重平衡的触发条件是什么" aria-label="Permalink to “kafka重平衡的触发条件是什么？”">​</a></h2><ul><li>消费者组成员发生变化 <ul><li>消费者的加入、退出或崩溃</li></ul></li><li>订阅主题分区数发生变化 <ul><li>主题分区增加或减少</li></ul></li><li>订阅主题发生变化 <ul><li>使用正则表达式订阅主题时，新的主题被匹配</li></ul></li></ul><h2 id="kafka发送失败如何处理" tabindex="-1">kafka发送失败如何处理 <a class="header-anchor" href="#kafka发送失败如何处理" aria-label="Permalink to “kafka发送失败如何处理”">​</a></h2><ul><li><strong>同步发送模式</strong> 捕获异常</li><li><strong>异步发送模式</strong> 在回调方法中捕获异常</li><li><strong>重试机制</strong><ul><li>设置重试次数</li></ul></li><li><strong>错误分类处理</strong><ul><li>可恢复错误 <ul><li>网络超时</li></ul></li><li>不可恢复错误 <ul><li>无效的主题</li></ul></li></ul></li><li>调整生产者配置 <ul><li>设置<code>acks</code>, 可以设置为all，确保所有副本都确认才返回成功</li></ul></li><li>使用死信队列 <ul><li>将发送失败的消息加入到死信队列中，以便后续处理</li></ul></li></ul><h3 id="kafka的分区分配策略有哪些" tabindex="-1">kafka的分区分配策略有哪些？ <a class="header-anchor" href="#kafka的分区分配策略有哪些" aria-label="Permalink to “kafka的分区分配策略有哪些？”">​</a></h3><ul><li><code>RangeAssignor</code></li><li><code>RoundRobinAssignor</code></li><li><code>StickerAssignor</code></li><li><code>CooperativeStickerAssignor</code></li></ul><h3 id="kafka默认的分区策略是什么" tabindex="-1">kafka默认的分区策略是什么？ <a class="header-anchor" href="#kafka默认的分区策略是什么" aria-label="Permalink to “kafka默认的分区策略是什么？”">​</a></h3><ul><li><code>DefaultPartitioner</code><ul><li>指定分区</li><li>基于key分配</li><li>轮询分配</li></ul></li></ul>',17)])])}const h=l(r,[["render",t]]);export{d as __pageData,h as default};
